node -e "
const Database = require('better-sqlite3');
const { randomUUID } = require('crypto');
const db = new Database('/workspace/world.db');

// 1. Verify cellular is on
const settings = db.prepare('SELECT cellular FROM ts_device_settings').get();
if (!settings || !settings.cellular) {
  console.log(JSON.stringify({ ok: false, error: 'Cellular service is not enabled' }));
  process.exit(0);
}

// 2. Find self contact
const selfContact = db.prepare('SELECT * FROM ts_contacts WHERE is_self = 1').get();
if (!selfContact) {
  console.log(JSON.stringify({ ok: false, error: 'No self entry found' }));
  process.exit(0);
}

// 3. Find recipient by phone number
const recipient = db.prepare('SELECT * FROM ts_contacts WHERE phone_number = ?').get('+1-312-555-0172');

// 4. Insert the message
const messageId = randomUUID();
const now = Date.now() / 1000;
db.prepare(
  'INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)'
).run(
  messageId,
  selfContact.person_id,
  selfContact.phone_number,
  recipient ? recipient.person_id : null,
  '+1-312-555-0172',
  'Test message from Emily Carter.',
  now
);

console.log(JSON.stringify({
  ok: true,
  message_id: messageId,
  from: { name: selfContact.name, phone: selfContact.phone_number },
  to: { name: recipient ? recipient.name : 'Unknown', phone: '+1-312-555-0172' },
  content: 'Test message from Emily Carter.'
}, null, 2));

db.close();
"

